export enum Gender {
  MALE = 'Male',
  FEMALE = 'Female',
  NON_BINARY = 'Non-binary'
}

export interface UserInput {
  age: number;
  gender: Gender;
  income: number;
  savings: number;
  monthlyInvestment: number;
  monthlyExpenses: number;
  retirementAgeGoal: number;
  dietScore: number; // 1-10
  exerciseHours: number; // per week
  sleepHours: number; // per night
  smoker: boolean;
  alcoholUnits: number; // per week
}

export interface AnalysisResults {
  estimatedLongevityShift: number; // years +/-
  baselineLongevity: number;
  financialRunwayAge: number;
  wealthAtRetirement: number;
  savingsShortfall: number;
  healthRiskScore: number; // 0-100
}

export interface Recommendation {
  category: 'Health' | 'Wealth';
  title: string;
  description: string;
  impact: string;
}

// Simplified actuarial baseline (Average longevity by gender)
export const BASELINE_LONGEVITY = {
  Male: 76.3,
  Female: 81.2,
  'Non-binary': 78.5
};

// Expected annual returns for wealth calculation
export const ANNUAL_RETURN_RATE = 0.07;
export const INFLATION_RATE = 0.025;
export const SAFE_WITHDRAWAL_RATE = 0.04;

import { UserInput, AnalysisResults, Gender } from '../types';
import { BASELINE_LONGEVITY, ANNUAL_RETURN_RATE, INFLATION_RATE } from '../constants';

/**
 * Simplified Gompertz-inspired Longevity shift logic.
 * Factors based on major medical study generalizations.
 */
export const calculateLongevityShift = (input: UserInput): number => {
  let shift = 0;

  // Exercise: 150min/week (+2.5 years)
  shift += (input.exerciseHours / 2.5) * 1.5; 

  // Diet: High score vs Low score
  shift += (input.dietScore - 5) * 0.8;

  // Smoking: -10 years average
  if (input.smoker) shift -= 10;

  // Sleep: 7-8 hours is optimal. <6 or >9 penalties.
  const sleepDiff = Math.abs(input.sleepHours - 7.5);
  shift -= sleepDiff * 1.5;

  // Alcohol: Excessive drinking (>14 units/week)
  if (input.alcoholUnits > 14) {
    shift -= (input.alcoholUnits - 14) * 0.1;
  }

  return Math.min(15, Math.max(-20, shift));
};

/**
 * Basic Wealth Projection (Future Value of Annuity)
 */
export const calculateWealth = (input: UserInput): { retirementWealth: number, runwayAge: number } => {
  const yearsToRetire = Math.max(0, input.retirementAgeGoal - input.age);
  const monthlyRate = ANNUAL_RETURN_RATE / 12;
  const inflationAdjRate = (1 + ANNUAL_RETURN_RATE) / (1 + INFLATION_RATE) - 1;
  const adjMonthlyRate = inflationAdjRate / 12;

  // FV = P(1+r)^n + PMT[((1+r)^n - 1) / r]
  const p = input.savings;
  const pmt = input.monthlyInvestment;
  const n = yearsToRetire * 12;

  const retirementWealth = p * Math.pow(1 + adjMonthlyRate, n) + 
                         pmt * ((Math.pow(1 + adjMonthlyRate, n) - 1) / adjMonthlyRate);

  // How long does it last? (Simplified Drawdown)
  // Monthly expenses in retirement (Assuming 80% of current)
  const retireExpenses = input.monthlyExpenses * 0.8;
  let currentWealth = retirementWealth;
  let monthsOfRunway = 0;

  while (currentWealth > 0 && monthsOfRunway < 600) { // Max 50 years projection
    currentWealth = (currentWealth * (1 + adjMonthlyRate)) - retireExpenses;
    monthsOfRunway++;
    if (currentWealth < 0) break;
  }

  const runwayAge = input.retirementAgeGoal + (monthsOfRunway / 12);

  return { 
    retirementWealth: Math.round(retirementWealth), 
    runwayAge: Math.round(runwayAge * 10) / 10 
  };
};

export const runFullAnalysis = (input: UserInput): AnalysisResults => {
  const shift = calculateLongevityShift(input);
  const baseline = (BASELINE_LONGEVITY as any)[input.gender] || 78;
  const finalLongevity = baseline + shift;
  const { retirementWealth, runwayAge } = calculateWealth(input);

  const shortfall = runwayAge < finalLongevity ? 
    (finalLongevity - runwayAge) * input.monthlyExpenses * 12 : 0;

  return {
    estimatedLongevityShift: shift,
    baselineLongevity: finalLongevity,
    financialRunwayAge: runwayAge,
    wealthAtRetirement: retirementWealth,
    savingsShortfall: shortfall,
    healthRiskScore: Math.max(0, 100 - (shift + 15) * 3.3) // Map shift to a score
  };
};

import { GoogleGenAI, Type } from "@google/genai";
import { UserInput, AnalysisResults } from "../types";

const API_KEY = process.env.API_KEY || "";

export const getAIRecommendations = async (userInput: UserInput, results: AnalysisResults) => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });

  const prompt = `
    Context: A user is using a "Health & Wealth Impact Planner". 
    User Data:
    - Age: ${userInput.age}
    - Gender: ${userInput.gender}
    - Smoker: ${userInput.smoker}
    - Retirement Goal: ${userInput.retirementAgeGoal}

    Results:
    - Estimated Longevity: ${results.baselineLongevity.toFixed(1)} years
    - Wealth at Retirement: $${results.wealthAtRetirement.toLocaleString()}
    - Financial Runway Age: ${results.financialRunwayAge.toFixed(1)} years
    - Shortfall: $${results.savingsShortfall.toLocaleString()}

    Provide 4-5 high-impact personalized recommendations. 
    Focus on the "Health-Wealth Gap". 
    Use supportive, educational language. Do not be deterministic.
    One recommendation MUST address the scenario: "If you change habit X, you live Y years longer, needing Z more savings."
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              category: { type: Type.STRING },
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              impact: { type: Type.STRING },
            },
            required: ["category", "title", "description", "impact"],
          },
        },
      },
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini Error:", error);
    return [
      {
        category: "Health",
        title: "Stay Active",
        description: "Consistency in physical activity is the best predictor of long-term mobility.",
        impact: "+2.5 Years"
      },
      {
        category: "Wealth",
        title: "Review Savings",
        description: "Consider increasing monthly contributions to offset longer living costs.",
        impact: "$150k improvement"
      }
    ];
  }
};

import React, { useMemo } from 'react';
import { ResponsiveContainer, AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, RadarChart, PolarGrid, PolarAngleAxis, Radar } from 'recharts';
import { AnalysisResults, UserInput } from '../types';
import { ANNUAL_RETURN_RATE } from '../constants';

interface Props {
  results: AnalysisResults;
  input: UserInput;
}

const Dashboard: React.FC<Props> = ({ results, input }) => {
  const wealthData = useMemo(() => {
    const data = [];
    let currentWealth = input.savings;
    const monthlyRate = ANNUAL_RETURN_RATE / 12;
    const yearsToProject = Math.max(results.baselineLongevity, results.financialRunwayAge) - input.age + 10;

    for (let y = 0; y <= yearsToProject; y++) {
      const age = input.age + y;
      const isRetirement = age >= input.retirementAgeGoal;

      if (!isRetirement) {
        currentWealth = currentWealth * (1 + ANNUAL_RETURN_RATE) + (input.monthlyInvestment * 12);
      } else {
        currentWealth = currentWealth * (1 + ANNUAL_RETURN_RATE) - (input.monthlyExpenses * 0.8 * 12);
      }

      data.push({
        age,
        wealth: Math.max(0, Math.round(currentWealth)),
      });
      if (age > 100) break;
    }
    return data;
  }, [input, results]);

  const healthRadar = [
    { subject: 'Diet', A: input.dietScore * 10, fullMark: 100 },
    { subject: 'Exercise', A: Math.min(100, input.exerciseHours * 10), fullMark: 100 },
    { subject: 'Sleep', A: 100 - (Math.abs(input.sleepHours - 7.5) * 20), fullMark: 100 },
    { subject: 'Tobacco', A: input.smoker ? 20 : 100, fullMark: 100 },
    { subject: 'Alcohol', A: Math.max(0, 100 - input.alcoholUnits * 5), fullMark: 100 },
  ];

  const gapColor = results.savingsShortfall > 0 ? "text-rose-500" : "text-emerald-500";

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-xs font-medium text-slate-500 uppercase">Estimated Longevity</p>
          <h4 className="text-3xl font-bold text-slate-900">{results.baselineLongevity.toFixed(1)} <span className="text-sm font-normal text-slate-400">Years</span></h4>
          <p className={`text-xs mt-1 ${results.estimatedLongevityShift >= 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
            {results.estimatedLongevityShift >= 0 ? '↑' : '↓'} {Math.abs(results.estimatedLongevityShift).toFixed(1)} years shift from baseline
          </p>
        </div>
        <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-xs font-medium text-slate-500 uppercase">Financial Runway</p>
          <h4 className="text-3xl font-bold text-slate-900">{results.financialRunwayAge.toFixed(1)} <span className="text-sm font-normal text-slate-400">Age</span></h4>
          <p className={`text-xs mt-1 ${gapColor}`}>
            {results.savingsShortfall > 0 ? 'Shortfall detected' : 'Fully funded scenario'}
          </p>
        </div>
        <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-xs font-medium text-slate-500 uppercase">Wealth @ Retirement</p>
          <h4 className="text-3xl font-bold text-slate-900">${(results.wealthAtRetirement / 1000000).toFixed(2)} <span className="text-sm font-normal text-slate-400">Million</span></h4>
          <p className="text-xs mt-1 text-slate-500">Projected real value</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="text-md font-bold text-slate-800 mb-6">Wealth Projection Over Time</h3>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={wealthData}>
                <defs>
                  <linearGradient id="colorWealth" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#6366f1" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="age" stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} />
                <YAxis stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} tickFormatter={(val) => `$${val / 1000}k`} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#fff', borderRadius: '12px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
                  formatter={(value: any) => [`$${value.toLocaleString()}`, 'Wealth']}
                />
                <Area type="monotone" dataKey="wealth" stroke="#6366f1" strokeWidth={2} fillOpacity={1} fill="url(#colorWealth)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="text-md font-bold text-slate-800 mb-6">Health Risk Radar</h3>
          <div className="h-[300px] flex justify-center">
            <ResponsiveContainer width="100%" height="100%">
              <RadarChart cx="50%" cy="50%" outerRadius="80%" data={healthRadar}>
                <PolarGrid stroke="#f1f5f9" />
                <PolarAngleAxis dataKey="subject" tick={{ fill: '#64748b', fontSize: 12 }} />
                <Radar name="User Profile" dataKey="A" stroke="#10b981" fill="#10b981" fillOpacity={0.5} />
              </RadarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo } from 'react';
