  occupationalHazard: number; // 1-5 (1 is desk job, 5 is high danger)
  educationLevel: Education;
  stressLevel: number; // 1-10

  // Financial
  income: number;
  savings: number;
  monthlyInvestment: number;
  monthlyExpenses: number;
