import { GoogleGenAI, Type } from "@google/genai";
import { UserInput, AnalysisResults } from "../types";

export const getAIRecommendations = async (userInput: UserInput, results: AnalysisResults) => {
  // Always initialize GoogleGenAI with { apiKey: process.env.API_KEY } directly
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Context: Professional "Health & Wealth Impact Planner" using actuarial models.
    User Profile:
    - Age: ${userInput.age}, Gender: ${userInput.gender}, Ethnicity: ${userInput.ethnicity}
    - Location: ${userInput.location}, Stress Level: ${userInput.stressLevel}/10, Education: ${userInput.educationLevel}
    - Habits: Smoker: ${userInput.smoker}, Diet: ${userInput.dietScore}/10, Drugs: ${userInput.recreationalDrugUse}
    - Medical: Chronic Disease: ${userInput.hasChronicDisease}, Genetic Risk: ${userInput.geneticPredisposition}/10
    - Environment: Air Quality: ${userInput.airQualityRating}/5, Occupational Hazard: ${userInput.occupationalHazard}/5
    - Financial: Income: $${userInput.income}/yr, Risk Tolerance: ${userInput.riskTolerance}/10, Insurance: $${userInput.insuranceCoverage}

    Analytic Results:
    - Life Expectancy: ${results.baselineLongevity.toFixed(1)} years (Shift: ${results.estimatedLongevityShift} years)
    - Wealth @ Retirement: $${results.wealthAtRetirement.toLocaleString()}
    - Income Allocation: Taxes: $${Math.round(results.incomeBreakdown.taxes)}, Essentials: $${results.incomeBreakdown.essential}, Savings: $${results.incomeBreakdown.savings}, Discretionary: $${Math.round(results.incomeBreakdown.discretionary)}
    - Health Risk Profile: Cardio: ${results.healthRiskBreakdown.cardiovascular}%, Metabolic: ${results.healthRiskBreakdown.metabolic}%, Psych: ${results.healthRiskBreakdown.psychological}%, Environ: ${results.healthRiskBreakdown.environmental}%
    - Insurance Gap: $${results.insuranceGap.toLocaleString()}

    Provide 4 highly specific recommendations in these categories: 'Health', 'Wealth', 'Environment'.
    One MUST be a "Health-Wealth Swap" scenario with specific figures (e.g. "By investing $200/mo into a healthier diet, you reduce metabolic risk by 15%, potentially adding 2.5 years of life, which requires $120k more in retirement savings but reduces long-term care costs by $300k").
    Include exact dollar amounts for suggested financial adjustments.
    Language: Professional, supportive, non-deterministic.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              category: { type: Type.STRING },
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              impact: { type: Type.STRING },
            },
            required: ["category", "title", "description", "impact"],
          },
        },
      },
    });

    // Access .text property directly (do not call as method)
    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Gemini Error:", error);
    return [
      {
        category: "Wealth",
        title: "Reallocate Discretionary Income",
        description: "Moving $300 from lifestyle to your 401k/IRA would close your shortfall by 85% given your high risk tolerance.",
        impact: "+$420k Final Wealth"
      },
      {
        category: "Health",
        title: "Metabolic Risk Mitigation",
        description: "Prioritizing high-protein, low-GI whole foods can lower your metabolic risk score from " + results.healthRiskBreakdown.metabolic + "% to under 25%.",
        impact: "+1.8 Years Life"
      }
    ];
  }
};

