import { UserInput, AnalysisResults, Gender, Education, IncomeBreakdown, HealthRiskBreakdown, EmploymentType } from '../types';
import { BASELINE_LONGEVITY, ANNUAL_RETURN_RATE, INFLATION_RATE } from '../constants';

export const calculateLongevityShift = (input: UserInput): number => {
  let shift = 0;

  // Lifestyle
  shift += (input.exerciseHours / 2.5) * 1.5; 
  shift += (input.dietScore - 6) * 0.9;
  if (input.smoker) shift -= 8.5;
  const sleepDiff = Math.abs(input.sleepHours - 7.5);
  shift -= sleepDiff * 1.2;
  if (input.alcoholUnits > 14) shift -= (input.alcoholUnits - 14) * 0.15;
  if (input.recreationalDrugUse === 'Regular') shift -= 5;
  else if (input.recreationalDrugUse === 'Occasional') shift -= 1.5;

  // Medical
  if (input.hasChronicDisease) shift -= 4.0;
  const baseline = (BASELINE_LONGEVITY as any)[input.gender] || 78;
  const familyDiff = input.familyLongevity - baseline;
  shift += familyDiff * 0.3; 
  shift -= (input.geneticPredisposition / 10) * 3;

  // Environmental
  shift += (input.airQualityRating - 3) * 0.8;
  shift -= (input.pollutionExposure - 1) * 0.6; // New factor
  shift += (input.healthcareAccess - 3) * 1.2; // New factor
  shift -= (input.occupationalHazard - 1) * 0.5;

  // Socio-economic
  shift -= (input.stressLevel / 10) * 2;
  const educationMap: Record<Education, number> = {
    [Education.HIGH_SCHOOL]: -1,
    [Education.BACHELORS]: 0,
    [Education.MASTERS]: 1.5,
    [Education.PHD]: 2.5
  };
  shift += educationMap[input.educationLevel];

  const employmentMap: Record<EmploymentType, number> = {
    'Full-time': 0.5,
    'Part-time': 0,
    'Self-employed': 0.2,
    'Unemployed': -1.5,
    'Retired': 0.3
  };
  shift += employmentMap[input.employmentType];

  return Math.min(18, Math.max(-25, shift));
};

export const calculateIncomeBreakdown = (input: UserInput): IncomeBreakdown => {
  const monthlyIncome = input.income / 12;

  let taxRate = 0.15;
  if (input.income > 50000) taxRate = 0.22;
  if (input.income > 100000) taxRate = 0.28;
  if (input.income > 200000) taxRate = 0.35;

  const taxes = monthlyIncome * taxRate;
  const savings = input.monthlyInvestment;
  const essential = input.monthlyExpenses;
  const discretionary = Math.max(0, monthlyIncome - taxes - savings - essential);

  return { essential, discretionary, savings, taxes };
};

export const calculateHealthRisks = (input: UserInput): HealthRiskBreakdown => {
  return {
    cardiovascular: Math.min(100, (input.smoker ? 40 : 10) + (input.alcoholUnits * 2) + (10 - input.exerciseHours * 5)),
    metabolic: Math.min(100, (10 - input.dietScore) * 8 + (input.alcoholUnits * 1.5)),
    psychological: Math.min(100, input.stressLevel * 8 + (Math.abs(input.sleepHours - 7.5) * 10)),
    environmental: Math.min(100, (6 - input.airQualityRating) * 10 + (input.pollutionExposure * 8) + (input.occupationalHazard * 6))
  };
};

export const calculateWealth = (input: UserInput): { retirementWealth: number, runwayAge: number, insuranceGap: number } => {
  const yearsToRetire = Math.max(0, input.retirementAgeGoal - input.age);

  const adjustedReturn = 0.03 + (input.riskTolerance / 10) * 0.07;
  const inflationAdjRate = (1 + adjustedReturn) / (1 + INFLATION_RATE) - 1;
  const adjMonthlyRate = inflationAdjRate / 12;

  const p = input.savings;
  const pmt = input.monthlyInvestment;
  const n = yearsToRetire * 12;

  const retirementWealth = p * Math.pow(1 + adjMonthlyRate, n) + 
                         pmt * ((Math.pow(1 + adjMonthlyRate, n) - 1) / adjMonthlyRate);

  const retireExpenses = input.monthlyExpenses * 0.85; 
  let currentWealth = retirementWealth;
  let monthsOfRunway = 0;

  while (currentWealth > 0 && monthsOfRunway < 600) {
    const monthlySpend = retireExpenses * Math.pow(1 + INFLATION_RATE / 12, monthsOfRunway);
    currentWealth = (currentWealth * (1 + adjMonthlyRate)) - monthlySpend;
    monthsOfRunway++;
    if (currentWealth < 0) break;
  }

  const runwayAge = input.retirementAgeGoal + (monthsOfRunway / 12);

  const targetCoverage = (input.income * 10) + (input.monthlyExpenses * 12 * 5);
  const insuranceGap = Math.max(0, targetCoverage - input.insuranceCoverage);

  return { 
    retirementWealth: Math.round(retirementWealth), 
    runwayAge: Math.round(runwayAge * 10) / 10,
    insuranceGap
  };
};

export const runFullAnalysis = (input: UserInput): AnalysisResults => {
  const shift = calculateLongevityShift(input);
  const baseline = (BASELINE_LONGEVITY as any)[input.gender] || 78;
  const finalLongevity = baseline + shift;
  const { retirementWealth, runwayAge, insuranceGap } = calculateWealth(input);
  const incomeBreakdown = calculateIncomeBreakdown(input);
  const healthRiskBreakdown = calculateHealthRisks(input);

  const shortfall = runwayAge < finalLongevity ? 
    (finalLongevity - runwayAge) * input.monthlyExpenses * 12 : 0;

  const probToRetire = Math.max(0.6, Math.min(0.99, 1 - (input.age / 100) + (shift / 100)));

  return {
    estimatedLongevityShift: shift,
    baselineLongevity: finalLongevity,
    financialRunwayAge: runwayAge,
    wealthAtRetirement: retirementWealth,
    savingsShortfall: shortfall,
    healthRiskScore: Math.max(0, 100 - (shift + 25) * 2),
    insuranceGap,
    probabilityOfSurvivalToRetirement: probToRetire,
    incomeBreakdown,
    healthRiskBreakdown
  };
};

