  const prompt = `
    Context: Professional "JeffreyWoo Health & Wealth Impact Planner" using actuarial models.
    Complete User Data:
    - Biometrics: BMI ${userInput.bmi}, BP ${userInput.bloodPressureSys}/${userInput.bloodPressureDia}, Sugar ${userInput.bloodSugarLevel}, VO2 ${userInput.vo2Max}, Steps ${userInput.dailySteps}
