    - Healthcare: Adherence ${userInput.medicationAdherence}/10, Checkups ${userInput.checkupFrequency}/yr, Preventive Access ${userInput.preventiveCareAccess}/5
    - Systems: Regional Mortality ${userInput.regionalMortalityTrend}/5, Climate Risk ${userInput.climateChangeImpactRisk}/5, Tech Access ${userInput.technologicalAccess}/5
    - Culture: Diet ${userInput.dietaryPattern}, Spiritual Practice: ${userInput.religiousSpiritualPractice}
    - Financial: Income $${userInput.income}/yr, Expenses $${userInput.monthlyExpenses}/mo, Insurance $${userInput.insuranceCoverage}

    Analytic Results:
    - Life Expectancy: ${results.baselineLongevity.toFixed(1)} years (Shift: ${results.estimatedLongevityShift.toFixed(1)} years)
    - Wealth @ Retirement: $${results.wealthAtRetirement.toLocaleString()}
    - Financial Runway: Age ${results.financialRunwayAge.toFixed(1)}
    - Insurance Gap: $${results.insuranceGap.toLocaleString()}

    Recommendations Required:
    1. One "Health-Wealth Swap": Calculate exact financial impact of a health change (e.g. "Improving Social Connection score from 4 to 8 adds 4.2 years, requiring $X more savings but saving $Y in potential depression/loneliness-related medical costs").
    2. One Genetic/Biometric focus: e.g. Telomere maintenance or Blood Sugar management.
    3. One Systemic/Environmental: e.g. Tech access for telemedicine.
    4. One Wealth adjustment based on new life expectancy.

    Format: Professional, empathetic, supportive. DO NOT predict death date. Use probabilities.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              category: { type: Type.STRING },
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              impact: { type: Type.STRING },
            },
            required: ["category", "title", "description", "impact"],
          },
        },
      },
    });

    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Gemini Error:", error);
    return [
      {
        category: "Health",
        title: "Bio-Age Calibration",
        description: "Given your epigenetic delta, prioritizing NAD+ precursor foods could slow telomere attrition.",
        impact: "+2.1 Years"
      },
      {
        category: "Wealth",
        title: "Longevity Adjusted Reserve",
        description: "Your high social connection level suggests a 15% longer retirement runway is probable; consider adding $400/mo to your growth portfolio.",
        impact: "+$180k Reserve"
      }
    ];
  }
};

